    { const char * tb_v1252 = "    stack_t ss, old;\n"; *(const char * *)tb_grow(v_lines) = tb_v1252; }
    { const char * tb_v1253 = "    ss.ss_sp = 0; ss.ss_size = 0; ss.ss_flags = SS_DISABLE;\n"; *(const char * *)tb_grow(v_lines) = tb_v1253; }
    { const char * tb_v1254 = "    if (sigaltstack(&ss, &old) == 0 && old.ss_sp) free(old.ss_sp);\n"; *(const char * *)tb_grow(v_lines) = tb_v1254; }
