    { const char * tb_v2605 = "TB_API unsigned long long tb_rand_state = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2605; }
    { const char * tb_v2606 = "// цвет из красного, зелёного и синего (0..255) — одно число 0xRRGGBB\n"; *(const char * *)tb_grow(v_lines) = tb_v2606; }
