    { const char * tb_v3035 = "// замок в ядре: одна команда xchg + прерывания выключены, пока замок у нас\n"; *(const char * *)tb_grow(v_lines) = tb_v3035; }
    { const char * tb_v3036 = "// (так прерывание не застрянет на замке, который держит прерванная задача)\n"; *(const char * *)tb_grow(v_lines) = tb_v3036; }
    { const char * tb_v3037 = "TB_INL unsigned long tb_lock_take(int *l) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3037; }
