    { const char * tb_v3059 = "// ---------- канал: очередь между потоками (channel int / text ...) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3059; }
    { const char * tb_v3060 = "// send кладёт в конец (очередь растёт, отправитель не ждёт), receive берёт из начала\n"; *(const char * *)tb_grow(v_lines) = tb_v3060; }
    { const char * tb_v3061 = "// и ждёт, пока что-то придёт. close: больше не пишут; each по каналу кончается,\n"; *(const char * *)tb_grow(v_lines) = tb_v3061; }
    { const char * tb_v3062 = "// когда он закрыт и пуст. Текст копируется: отправитель может удалить свою память.\n"; *(const char * *)tb_grow(v_lines) = tb_v3062; }
