    { const char * tb_v3894 = "// высота строки — size * 5 / 4; линия букв — так, чтобы верх и низ шрифта легли в эту строку\n"; *(const char * *)tb_grow(v_lines) = tb_v3894; }
    { const char * tb_v3895 = "static int tb_font_base(const tb_font_t *f, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3895; }
    { const char * tb_v3896 = "    double lh = size * 5 / 4.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3896; }
    { const char * tb_v3897 = "    return (int)floor(lh * f->asc / (f->asc - f->desc) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v3897; }
    { const char * tb_v3898 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3898; }
    { const char * tb_v3899 = "static unsigned tb_utf8_next(const unsigned char **pp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3899; }
    { const char * tb_v3900 = "    const unsigned char *p = *pp;\n"; *(const char * *)tb_grow(v_lines) = tb_v3900; }
    { const char * tb_v3901 = "    unsigned u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3901; }
    { const char * tb_v3902 = "    if (u >= 0x80) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3902; }
    { const char * tb_v3903 = "        int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3903; }
    { const char * tb_v3904 = "        u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v3904; }
    { const char * tb_v3905 = "        while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v3905; }
    { const char * tb_v3906 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3906; }
    { const char * tb_v3907 = "    *pp = p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3907; }
    { const char * tb_v3908 = "    return u;\n"; *(const char * *)tb_grow(v_lines) = tb_v3908; }
    { const char * tb_v3909 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3909; }
    { const char * tb_v3910 = "TB_API long long tb_text_width(long long fi, const char *s, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3910; }
    { const char * tb_v3911 = "    if (fi < 0 || fi >= tb_nfonts || size <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3911; }
    { const char * tb_v3912 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v3912; }
    { const char * tb_v3913 = "    double scale = (double)size / f->upem, pen = 0, best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3913; }
    { const char * tb_v3914 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3914; }
    { const char * tb_v3915 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3915; }
    { const char * tb_v3916 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v3916; }
    { const char * tb_v3917 = "        if (u == '\\n') { if (pen > best) best = pen; pen = 0; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3917; }
    { const char * tb_v3918 = "        pen += tb_ttf_adv(f, tb_ttf_glyph(f, u)) * scale;\n"; *(const char * *)tb_grow(v_lines) = tb_v3918; }
    { const char * tb_v3919 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3919; }
    { const char * tb_v3920 = "    if (pen > best) best = pen;\n"; *(const char * *)tb_grow(v_lines) = tb_v3920; }
    { const char * tb_v3921 = "    return (long long)floor(best + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v3921; }
    { const char * tb_v3922 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3922; }
    { const char * tb_v3923 = "TB_API void tb_draw_image_a(long long id, long long x, long long y);\n"; *(const char * *)tb_grow(v_lines) = tb_v3923; }
    { const char * tb_v3924 = "TB_API void tb_draw_font(long long fi, long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3924; }
    { const char * tb_v3925 = "    if (!tb_px || fi < 0 || fi >= tb_nfonts || size <= 0 || size > 1000) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3925; }
    { const char * tb_v3926 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v3926; }
    { const char * tb_v3927 = "    double scale = (double)size / f->upem, pen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3927; }
    { const char * tb_v3928 = "    long long base = y + tb_font_base(f, size), lh = size * 5 / 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v3928; }
    { const char * tb_v3929 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3929; }
    { const char * tb_v3930 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3930; }
    { const char * tb_v3931 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v3931; }
    { const char * tb_v3932 = "        if (u == '\\n') { pen = 0; base += lh; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3932; }
