    { const char * tb_v3938 = "        if (gc->img >= 0) tb_draw_image_a(gc->img, gx + gc->left, base + gc->top);\n"; *(const char * *)tb_grow(v_lines) = tb_v3938; }
    { const char * tb_v3939 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3939; }
