    { const char * tb_v3981 = "TB_API long long tb_gpu_frames = 0, tb_gpu_bad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3981; }
    { const char * tb_v3982 = "TB_API void tb_gpu_flush(int present);   // своя у каждой системы: Metal или Vulkan\n"; *(const char * *)tb_grow(v_lines) = tb_v3982; }
    { const char * tb_v3983 = "TB_API void tb_gpu_vsync(void);          // включить или выключить ожидание экрана (tb_gpu_nosync)\n"; *(const char * *)tb_grow(v_lines) = tb_v3983; }
    { const char * tb_v3984 = "TB_API int tb_gpu_nosync = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3984; }
