    { const char * tb_v4007 = "    long long n = (long long)tb_gw * tb_gh, bad = 0, first = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4007; }
    { const char * tb_v4008 = "    for (long long i = 0; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v4008; }
    { const char * tb_v4009 = "        if (((tb_gpu_back[i] ^ tb_px[i]) & 0xFFFFFF) != 0) { if (first < 0) first = i; bad++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4009; }
    { const char * tb_v4010 = "    if (bad) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4010; }
