    { const char * tb_v4043 = "TB_API void tb_gpu_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4043; }
    { const char * tb_v4044 = "    if (r < 0 || cx + r < 0 || cy + r < 0 || cx - r >= tb_gw || cy - r >= tb_gh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4044; }
    { const char * tb_v4045 = "    if (r <= 16384) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4045; }
    { const char * tb_v4046 = "        long long x0 = cx - r < 0 ? 0 : cx - r, y0 = cy - r < 0 ? 0 : cy - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v4046; }
    { const char * tb_v4047 = "        long long x1 = cx + r + 1 > tb_gw ? tb_gw : cx + r + 1, y1 = cy + r + 1 > tb_gh ? tb_gh : cy + r + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4047; }
    { const char * tb_v4048 = "        tb_gpu_add(x0, y0, x1, y1, cx, cy, (uint32_t)c & 0xFFFFFF, (1u << 30) | (uint32_t)r);\n"; *(const char * *)tb_grow(v_lines) = tb_v4048; }
    { const char * tb_v4049 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4049; }
    { const char * tb_v4050 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4050; }
    { const char * tb_v4051 = "    // огромный круг: по строкам, полосками (то же правило i*i + j*j <= r*r + r)\n"; *(const char * *)tb_grow(v_lines) = tb_v4051; }
    { const char * tb_v4052 = "    long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v4052; }
    { const char * tb_v4053 = "    for (long long j = ja; j <= jb; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4053; }
    { const char * tb_v4054 = "        long long rest = r * r + r - j * j, i = (long long)sqrt((double)rest);\n"; *(const char * *)tb_grow(v_lines) = tb_v4054; }
    { const char * tb_v4055 = "        while (i * i > rest) i--;\n"; *(const char * *)tb_grow(v_lines) = tb_v4055; }
    { const char * tb_v4056 = "        while ((i + 1) * (i + 1) <= rest) i++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4056; }
    { const char * tb_v4057 = "        tb_gpu_rect(cx - i, cy + j, 2 * i + 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v4057; }
    { const char * tb_v4058 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4058; }
    { const char * tb_v4059 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4059; }
