    { const char * tb_v6375 = "// показать кадр, принять клавиши и мышь, держать 60 кадров в секунду; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v6375; }
    { const char * tb_v6376 = "// окно поменяло размер: новый кадр, старое остаётся в левом верхнем углу, новое место — чёрное\n"; *(const char * *)tb_grow(v_lines) = tb_v6376; }
    { const char * tb_v6377 = "TB_API void tb_apply_resize(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6377; }
    { const char * tb_v6378 = "    if (!tb_new_w) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6378; }
