    { const char * tb_v6399 = "    if (nosync != tb_gpu_nosync) { tb_gpu_nosync = nosync; if (tb_gpu_on) tb_gpu_vsync(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6399; }
    { const char * tb_v6400 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6400; }
