    { const char * tb_v6443 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6443; }
    { const char * tb_v6444 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6444; }
    { const char * tb_v6445 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6445; }
    { const char * tb_v6446 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v6446; }
    { const char * tb_v6447 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6447; }
