    { const char * tb_v6453 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6453; }
    { const char * tb_v6454 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6454; }
