    { const char * tb_v6633 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v6633; }
    { const char * tb_v6634 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6634; }
