    { const char * tb_v6860 = "// ---- 3D в целых числах: так же считает видеокарта (compiler/gpu/tb3.vert, tb.metal) ----\n"; *(const char * *)tb_grow(v_lines) = tb_v6860; }
    { const char * tb_v6861 = "// деление с округлением вниз (b > 0); через числа без знака — одинаково на любой видеокарте\n"; *(const char * *)tb_grow(v_lines) = tb_v6861; }
    { const char * tb_v6862 = "TB_INL long long tb_fdiv(long long a, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6862; }
    { const char * tb_v6863 = "    return a >= 0 ? (long long)((unsigned long long)a / (unsigned long long)b)\n"; *(const char * *)tb_grow(v_lines) = tb_v6863; }
    { const char * tb_v6864 = "                  : -(long long)(((unsigned long long)(-a) + (unsigned long long)b - 1) / (unsigned long long)b);\n"; *(const char * *)tb_grow(v_lines) = tb_v6864; }
    { const char * tb_v6865 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6865; }
    { const char * tb_v6866 = "// фокус экрана × 256 (угол обзора 60°)\n"; *(const char * *)tb_grow(v_lines) = tb_v6866; }
    { const char * tb_v6867 = "TB_INL long long tb_m3_f(void) { return tb_rnd(tb_gh / 2.0 / tan(30 * 3.14159265358979323846 / 180) * 256); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6867; }
    { const char * tb_v6868 = "// угол сетки p (× 4096) по записи r: место на экране (целые точки) и глубина D = 2^24 - 2^24 * zn / z, zn = 205 / 4096\n"; *(const char * *)tb_grow(v_lines) = tb_v6868; }
    { const char * tb_v6869 = "TB_INL void tb_m3_corner(const int32_t *r, const int32_t *p, long long f, long long *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6869; }
    { const char * tb_v6870 = "    long long c[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v6870; }
    { const char * tb_v6871 = "    for (int k = 0; k < 3; k++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6871; }
    { const char * tb_v6872 = "        c[k] = (((long long)r[4 * k] * p[0] + (long long)r[4 * k + 1] * p[1] + (long long)r[4 * k + 2] * p[2]) >> 30) + r[4 * k + 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v6872; }
    { const char * tb_v6873 = "    o[0] = ((long long)tb_gw * 128 + tb_fdiv(f * c[0], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v6873; }
