    { const char * tb_v6875 = "    o[2] = 16777216 - tb_fdiv(205LL << 24, c[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6875; }
    { const char * tb_v6876 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6876; }
    { const char * tb_v6877 = "// треугольник a, b, c (x, y, D): 0 — рисовать нечего (ребром к нам или невидимая грань); иначе углы\n"; *(const char * *)tb_grow(v_lines) = tb_v6877; }
    { const char * tb_v6878 = "// по кругу «как надо» в t и плоскость глубины в pl — то же, что tb_tri3_plane, только в целых\n"; *(const char * *)tb_grow(v_lines) = tb_v6878; }
    { const char * tb_v6879 = "TB_INL int tb_m3_tri(const long long *a, const long long *b, const long long *c, int cull, long long *t, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6879; }
    { const char * tb_v6880 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6880; }
    { const char * tb_v6881 = "    if (area == 0 || (cull > 0 && area > 0) || (cull < 0 && area < 0)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6881; }
    { const char * tb_v6882 = "    if (area < 0) { const long long *k = b; b = c; c = k; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6882; }
    { const char * tb_v6883 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = b[2] - a[2], d2 = c[2] - a[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v6883; }
    { const char * tb_v6884 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v6884; }
    { const char * tb_v6885 = "    long long C = 64 * a[2] - 2 * A * a[0] - 2 * B * a[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v6885; }
    { const char * tb_v6886 = "    pl[0] = (uint32_t)A; pl[1] = (uint32_t)B; pl[2] = (uint32_t)C;\n"; *(const char * *)tb_grow(v_lines) = tb_v6886; }
    { const char * tb_v6887 = "    t[0] = a[0]; t[1] = a[1]; t[2] = b[0]; t[3] = b[1]; t[4] = c[0]; t[5] = c[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v6887; }
    { const char * tb_v6888 = "    return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6888; }
    { const char * tb_v6889 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6889; }
    { const char * tb_v6890 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v6890; }
    { const char * tb_v6891 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v6891; }
    { const char * tb_v6892 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v6892; }
    { const char * tb_v6893 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6893; }
    { const char * tb_v6894 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v6894; }
    { const char * tb_v6895 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v6895; }
    { const char * tb_v6896 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6896; }
    { const char * tb_v6897 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6897; }
    { const char * tb_v6898 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v6898; }
    { const char * tb_v6899 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6899; }
    { const char * tb_v6900 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6900; }
    { const char * tb_v6901 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v6901; }
    { const char * tb_v6902 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6902; }
    { const char * tb_v6903 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6903; }
    { const char * tb_v6904 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v6904; }
    { const char * tb_v6905 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v6905; }
    { const char * tb_v6906 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v6906; }
    { const char * tb_v6907 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6907; }
    { const char * tb_v6908 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6908; }
    { const char * tb_v6909 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v6909; }
    { const char * tb_v6910 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6910; }
    { const char * tb_v6911 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6911; }
    { const char * tb_v6912 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v6912; }
    { const char * tb_v6913 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v6913; }
    { const char * tb_v6914 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6914; }
    { const char * tb_v6915 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6915; }
    { const char * tb_v6916 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v6916; }
    { const char * tb_v6917 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6917; }
    { const char * tb_v6918 = "    return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v6918; }
    { const char * tb_v6919 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6919; }
    { const char * tb_v6920 = "// сетки для видеокарты: у каждой сначала углы (x, y, z, 0), потом треугольники (номера углов, цвет)\n"; *(const char * *)tb_grow(v_lines) = tb_v6920; }
    { const char * tb_v6921 = "TB_API long long tb_mesh_pack(int32_t *dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6921; }
    { const char * tb_v6922 = "    long long at = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6922; }
    { const char * tb_v6923 = "    for (long long i = 0; i < tb_nmesh; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6923; }
    { const char * tb_v6924 = "        tb_mesh *m = &tb_meshes[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6924; }
    { const char * tb_v6925 = "        m->gv = at; m->gt = at + m->nv;\n"; *(const char * *)tb_grow(v_lines) = tb_v6925; }
    { const char * tb_v6926 = "        if (dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6926; }
    { const char * tb_v6927 = "            memcpy(dst + 4 * at, m->vi, sizeof(int32_t) * 4 * (size_t)m->nv);\n"; *(const char * *)tb_grow(v_lines) = tb_v6927; }
    { const char * tb_v6928 = "            for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6928; }
    { const char * tb_v6929 = "                int32_t *o = dst + 4 * (m->gt + t);\n"; *(const char * *)tb_grow(v_lines) = tb_v6929; }
    { const char * tb_v6930 = "                for (int k = 0; k < 3; k++) o[k] = (int32_t)(m->t[3 * t + k] + m->gv);\n"; *(const char * *)tb_grow(v_lines) = tb_v6930; }
    { const char * tb_v6931 = "                o[3] = (int32_t)(m->c[t] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v6931; }
    { const char * tb_v6932 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v6932; }
    { const char * tb_v6933 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6933; }
    { const char * tb_v6934 = "        at += m->nv + m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6934; }
    { const char * tb_v6935 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6935; }
    { const char * tb_v6936 = "    return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v6936; }
    { const char * tb_v6937 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6937; }
    { const char * tb_v6938 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6938; }
    { const char * tb_v6939 = "    tb_mesh *m = &tb_meshes[g->x0];\n"; *(const char * *)tb_grow(v_lines) = tb_v6939; }
