    { const char * tb_v6963 = "TB_API long long *tb_3ist = 0, tb_3igen = 0;   // какой угол уже посчитан в этом вызове (процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v6963; }
    { const char * tb_v6964 = "static void tb_m3_draw(tb_m3_go *go, long long t0, long long tn) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6964; }
