    { const char * tb_v6998 = "// куски сетки: треугольники делятся пополам по самой длинной стороне, пока в куске не больше 256.\n"; *(const char * *)tb_grow(v_lines) = tb_v6998; }
    { const char * tb_v6999 = "// Треугольники переставляются так, чтобы каждый кусок шёл подряд; у каждого куска свой шар\n"; *(const char * *)tb_grow(v_lines) = tb_v6999; }
    { const char * tb_v7000 = "static int tb_kd_ax;\n"; *(const char * *)tb_grow(v_lines) = tb_v7000; }
